 p=economics.OUTPUTS["train"];assert hashlib.sha256(p.read_bytes()).hexdigest()=="1f42b7649aa6e073fa8bc6019095d9272754c7a318e93153d6d08db1f6c2c130";x=json.loads(p.read_text());core={k:v for k,v in x.items() if k!="manifest_hash"};assert x["manifest_hash"]==economics.canonical_hash(core);assert x["passed"] is False and x["decision"]=="terminal_reject_no_repair" and x["later_stage_outcomes_opened"] is False;assert x["primary"]["base"]["absolute_return_pct"]< -9 and x["primary"]["stress"]["absolute_return_pct"]< -11;assert not economics.OUTPUTS["test"].exists() and not economics.OUTPUTS["eval"].exists() and not economics.OUTPUTS["final"].exists()
